import React, { useState } from 'react';
import type { Room } from 'trystero/torrent';
import { Skill, GameState } from '../../types/game';
import { SkillView } from '../shared/SkillView'
import BasicObjectView from '../ui/BasicObjectView';
import Modal from '../shared/Modal';
import { Grid, List, Zap } from 'lucide-react';

interface SkillsPanelProps {
  skills: Skill[];
  room?: Room;
  gameState: GameState;
  onGameStateChange: (newState: GameState) => void;
  actorId?: string;
  isModal?: boolean;
  onClose?: () => void;
}

export function SkillsPanel({
  skills,
  room,
  gameState,
  onGameStateChange,
  actorId,
  isModal = true,
  onClose
}: SkillsPanelProps) {
  const [selectedSkill, setSelectedSkill] = useState<Skill | null>(null);
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');

  const content = (
    <>
      <div className="flex justify-between items-center mb-4">
        <div className="flex items-center gap-2">
          <Zap className="w-5 h-5" />
          <h2 className="text-xl font-bold">Skills</h2>
        </div>
        <button
          onClick={() => setViewMode(viewMode === 'grid' ? 'list' : 'grid')}
          className="p-2 rounded-md hover:bg-gray-100 dark:hover:bg-gray-700"
        >
          {viewMode === 'grid' ? <List size={20} /> : <Grid size={20} />}
        </button>
      </div>

      {skills.length === 0 ? (
        <div className="flex-1 flex items-center justify-center text-gray-500">
          No skills learned
        </div>
      ) : (
        <div className="flex-1 overflow-visible">
          {viewMode === 'grid' ? (
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-4">
              {skills.map((skill) => (
                <div key={skill.id} className="relative">
                  <BasicObjectView
                    name={skill.name}
                    imageId={skill.image}
                    size="md"
                    onClick={() => setSelectedSkill(skill)}
                    action={{
                      onClick: () => setSelectedSkill(skill),
                      content: skill.usesLeft ?? skill.uses ?? '∞'
                    }}
                  />
                </div>
              ))}
            </div>
          ) : (
            <div className="space-y-2">
              {skills.map((skill) => (
                <div
                  key={skill.id}
                  onClick={() => setSelectedSkill(skill)}
                  className="flex items-center p-4 border rounded-lg hover:bg-gray-50 dark:hover:bg-gray-700 cursor-pointer"
                >
                  <BasicObjectView
                    name={skill.name}
                    imageId={skill.image}
                    size="sm"
                    action={{
                      onClick: () => setSelectedSkill(skill),
                      content: skill.usesLeft ?? skill.uses ?? '∞'
                    }}
                  />
                  <div className="ml-4">
                    <h4 className="font-medium">{skill.name}</h4>
                    <div className="text-sm text-gray-500">
                      SP Cost: {skill.spCost} • Damage: {skill.damage}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      {/* Skill View Modal */}
      {selectedSkill && (
        <Modal
          isOpen={!!selectedSkill}
          onClose={() => setSelectedSkill(null)}
        >
          <SkillView
            skill={selectedSkill}
            onClose={() => setSelectedSkill(null)}
            room={room}
            gameState={gameState}
            onGameStateChange={onGameStateChange}
            actorId={actorId}
          />
        </Modal>
      )}
    </>
  );

  if (!isModal) {
    return content;
  }

  return (
    <Modal
      isOpen={true}
      onClose={onClose || (() => {})}
      className="max-w-4xl"
    >
      {content}
    </Modal>
  );
}