// src/components/DungeonMaster/DMView.tsx
import React, { useEffect } from 'react';
import { Tabs, TabsList, TabsTrigger, TabsContent } from '../ui/tabs';
import { DMViewProps, InventorySlot, Item } from '../../types/game';
import { CharacterTab } from './Tabs/CharacterTab';
import { VisualsTab } from './Tabs/VisualsTab';
import { CatalogTab } from './Tabs/CatalogTab';
import { EncounterTab } from './Tabs/EncounterTab';
import { BattleTab } from './Tabs/BattleTab';
import { SettingsTab } from './Tabs/SettingsTab';
import { CharacterActions } from '../../actions/characterActions';
import { EquipmentActions } from '../../actions/equipmentActions';


type TabType = 'characters' | 'visuals' | 'catalog' | 'encounter' | 'battle' | 'settings';

export function DMView({ gameState, onGameStateChange, room, isRoomCreator = true }: DMViewProps) {
  const tabs: { id: TabType; label: string }[] = [
    { id: 'characters', label: 'Characters' },
    { id: 'visuals', label: 'Visuals' },
    { id: 'catalog', label: 'Catalog' },
    { id: 'encounter', label: 'Encounter' },
    { id: 'battle', label: 'Battle' },
    { id: 'settings', label: 'Settings' }
  ];

  // Set up action handlers for character-related actions
  useEffect(() => {
    if (!room || !isRoomCreator) return;

    // Character Creation Handler
    const [_, getCharCreate] = room.makeAction(CharacterActions.CREATE);
    getCharCreate(({ character, playerId }) => {
      console.log(`DM received character creation request from ${playerId}:`, character);
      const newId = crypto.randomUUID();
      const newCharacter = { ...character, id: newId };
      
      onGameStateChange({
        ...gameState,
        party: [...gameState.party, newCharacter]
      });
    });

    // Character Update Handler
    const [__, getCharUpdate] = room.makeAction(CharacterActions.UPDATE);
    getCharUpdate(({ id, updates, playerId }) => {
      console.log(`DM received character update request from ${playerId} for character ${id}:`, updates);
      onGameStateChange({
        ...gameState,
        party: gameState.party.map(char =>
          char.id === id ? { ...char, ...updates } : char
        )
      });
    });

    // Character Delete Handler
    const [___, getCharDelete] = room.makeAction(CharacterActions.DELETE);
    getCharDelete(({ id, playerId }) => {
      console.log(`DM received character deletion request from ${playerId} for character ${id}`);
      onGameStateChange({
        ...gameState,
        party: gameState.party.filter(char => char.id !== id)
      });
    });

    // Character Selection Handler
    const [____, getCharSelect] = room.makeAction(CharacterActions.SELECT);
    getCharSelect(({ characterId, playerId }) => {
      console.log(`DM received character selection request from ${playerId} for character ${characterId}`);
      onGameStateChange({
        ...gameState,
        party: gameState.party.map(char =>
          char.id === characterId
            ? { ...char, playerId }
            : char.playerId === playerId
            ? { ...char, playerId: undefined }
            : char
        )
      });
    });

    const [_____, getEquipItem] = room.makeAction(EquipmentActions.EQUIP);
    getEquipItem(({ itemId, characterId, playerId }, peerId) => {
      console.log(`Player ${playerId} requested to equip item ${itemId} on character ${characterId}`);
      
      const character = gameState.party.find(char => char.id === characterId);
      if (!character) return;

      const inventorySlot = character.inventory.find(([item]) => item.id === itemId);
      if (!inventorySlot) return;

      const [itemToEquip, currentCount] = inventorySlot;

      // Create properly typed inventory and equipment arrays
      const updatedInventory: InventorySlot[] = character.inventory
        .map(([item, count]): InventorySlot => 
          item.id === itemId ? [item, count - 1] : [item, count]
        )
        .filter(([_, count]) => count > 0);

      const updatedEquipment: Item[] = [...character.equipment, itemToEquip];

      // Update game state
      onGameStateChange({
        ...gameState,
        party: gameState.party.map(char =>
          char.id === characterId
            ? { ...char, inventory: updatedInventory, equipment: updatedEquipment }
            : char
        )
      });
    });

  const [______, getUnequipItem] = room.makeAction(EquipmentActions.UNEQUIP);
  // Handle unequipping items
  getUnequipItem(({ itemId, characterId, playerId }, peerId) => {
    console.log(`Player ${playerId} requested to unequip item ${itemId} from character ${characterId}`);
    
    const character = gameState.party.find(char => char.id === characterId);
    if (!character) return;

    const itemToUnequip = character.equipment.find(item => item.id === itemId);
    if (!itemToUnequip) return;

    // Create properly typed inventory and equipment arrays
    const existingInventorySlot = character.inventory.find(([item]) => item.id === itemId);
    const updatedInventory: InventorySlot[] = existingInventorySlot
      ? character.inventory.map(([item, count]): InventorySlot =>
          item.id === itemId ? [item, count + 1] : [item, count]
        )
      : [...character.inventory, [itemToUnequip, 1] as InventorySlot];

    const updatedEquipment: Item[] = character.equipment.filter(item => item.id !== itemId);

    // Update game state
    onGameStateChange({
      ...gameState,
      party: gameState.party.map(char =>
        char.id === characterId
          ? { ...char, inventory: updatedInventory, equipment: updatedEquipment }
          : char
      )
    });
  });
    // Cleanup function
    return () => {
      // Trystero's room.leave() will handle cleanup of action handlers
    };
  }, [room, isRoomCreator, gameState, onGameStateChange]);

  return (
      <Tabs defaultValue="characters" className="w-full h-full">
        <TabsList className="w-full flex justify-start border-b border-gray-200 bg-transparent">
          {tabs.map(({ id, label }) => (
            <TabsTrigger
              key={id}
              value={id}
              className="px-4 py-2 text-sm font-medium data-[state=active]:border-b-2 data-[state=active]:border-blue-500 data-[state=active]:text-blue-600"
            >
              {label}
            </TabsTrigger>
          ))}
        </TabsList>

        <TabsContent value="characters">
          <CharacterTab 
            gameState={gameState} 
            onGameStateChange={onGameStateChange} 
            room={room}
            isRoomCreator={isRoomCreator}
          />
        </TabsContent>

        <TabsContent value="visuals">
        <VisualsTab 
            gameState={gameState}
            onGameStateChange={onGameStateChange}
            room={room}
            isRoomCreator={true}
          />
        </TabsContent>

        <TabsContent value="catalog">
          <CatalogTab 
            gameState={gameState}
            onGameStateChange={onGameStateChange}
            room={room}
          />
        </TabsContent>

        <TabsContent value="encounter">
          <EncounterTab 
            gameState={gameState}
            onGameStateChange={onGameStateChange}
            room={room}
          />
        </TabsContent>

        <TabsContent value="battle">
          <BattleTab 
            gameState={gameState}
            onGameStateChange={onGameStateChange}
            room={room}
            isRoomCreator={isRoomCreator}
          />
        </TabsContent>

        <TabsContent value="settings">
          <SettingsTab
            gameState={gameState}
            onGameStateChange={onGameStateChange}
            isRoomCreator={isRoomCreator}
          />
        </TabsContent>
      </Tabs>
  );
}