// src/actions/itemActions.ts
import type { Room } from 'trystero/torrent';
import type { GameState, Item, InteractiveActor, Character, Entity, InventorySlot, Inventory } from '../types/game';
import { selfId } from 'trystero';

export const ItemActions = {
  CREATE: 'itemCreate',
  UPDATE: 'itemUpdate',
  DELETE: 'itemDelete',
  GIVE: 'itemGive',    // Transfer item between any actors
  USE: 'itemUse',      // Use an item (if it has uses)
} as const;

// Updated payload to use actor IDs instead of specifically character IDs
interface ItemGivePayload {
  itemId: string;
  fromActorId: string;
  toActorId: string;
  quantity: number;
  playerId: string;
}

// Other interfaces remain the same...
interface ItemCreatePayload {
  item: Omit<Item, 'id'>;
  playerId: string;
}

interface ItemUpdatePayload {
  id: string;
  updates: Partial<Item>;
  playerId: string;
}

interface ItemDeletePayload {
  id: string;
  playerId: string;
}

interface ItemUsePayload {
  itemId: string;
  actorId: string;  // Changed to actorId to be consistent
  playerId: string;
}

// Helper function to find an actor in either party or entities
function findActor(gameState: GameState, actorId: string): InteractiveActor | undefined {
    const partyMember = gameState.party.find(char => char.id === actorId);
    if (partyMember) return partyMember;
    return gameState.entities.find(entity => entity.id === actorId);
  }

// Helper function to update an actor's inventory
function updateActorInventory(
    actor: InteractiveActor,
    itemId: string,
    quantity: number,
    operation: 'add' | 'remove',
    globalItems: Item[]
  ): InteractiveActor {
    const existingSlot = actor.inventory.find(([item]) => item.id === itemId);
    
    if (operation === 'remove' && existingSlot) {
      const updatedInventory: Inventory = actor.inventory
        .map(([item, count]): InventorySlot => {
          if (item.id === itemId) {
            return [item, count - quantity];
          }
          return [item, count];
        })
        .filter(([_, count]) => count > 0);
  
      return { ...actor, inventory: updatedInventory };
    }
    
    if (operation === 'add') {
      if (existingSlot) {
        // Update existing stack
        const updatedInventory: Inventory = actor.inventory.map(([item, count]): InventorySlot => {
          if (item.id === itemId) {
            return [item, count + quantity];
          }
          return [item, count];
        });
        return { ...actor, inventory: updatedInventory };
      } else {
        // Add new stack
        const newItem = globalItems.find((item: Item) => item.id === itemId);
        if (!newItem) return actor;
        
        const newInventory: Inventory = [...actor.inventory, [newItem, quantity]];
        return {
          ...actor,
          inventory: newInventory
        };
      }
    }
  
    return actor;
  }

export function setupItemActions(
  room: Room,
  gameState: GameState,
  onGameStateChange: (newState: GameState) => void,
  isRoomCreator: boolean
) {
  const [sendItemCreate, getItemCreate] = room.makeAction<ItemCreatePayload>(ItemActions.CREATE);
  const [sendItemUpdate, getItemUpdate] = room.makeAction<ItemUpdatePayload>(ItemActions.UPDATE);
  const [sendItemDelete, getItemDelete] = room.makeAction<ItemDeletePayload>(ItemActions.DELETE);
  const [sendItemGive, getItemGive] = room.makeAction<ItemGivePayload>(ItemActions.GIVE);
  const [sendItemUse, getItemUse] = room.makeAction<ItemUsePayload>(ItemActions.USE);

  if (isRoomCreator) {
    // Handle item creation
    getItemCreate(({ item, playerId }, peerId) => {
      console.log(`Player ${playerId} requested to create item:`, item);
      const newId = crypto.randomUUID();
      const newItem: Item = { ...item, id: newId };
      
      onGameStateChange({
        ...gameState,
        globalCollections: {
          ...gameState.globalCollections,
          items: [...gameState.globalCollections.items, newItem]
        }
      });
    });

    // Handle item transfer between any actors
    getItemGive(({ itemId, fromActorId, toActorId, quantity, playerId }, peerId) => {
        console.log(`Player ${playerId} requested to transfer item ${itemId} from ${fromActorId} to ${toActorId}`);
        
        let updatedParty = [...gameState.party];
        let updatedEntities = [...gameState.entities];
  
        // Update source actor
        const fromActor = findActor(gameState, fromActorId);
        if (fromActor) {
          const updatedFromActor = updateActorInventory(
            fromActor, 
            itemId, 
            quantity, 
            'remove',
            gameState.globalCollections.items
          );
          
          if ('equipment' in updatedFromActor) {
            // It's a character
            updatedParty = updatedParty.map(char => 
              char.id === fromActorId ? updatedFromActor as Character : char
            );
          } else {
            // It's an entity
            updatedEntities = updatedEntities.map(entity =>
              entity.id === fromActorId ? updatedFromActor as Entity : entity
            );
          }
        }
  
        // Update target actor
        const toActor = findActor(gameState, toActorId);
        if (toActor) {
          const updatedToActor = updateActorInventory(
            toActor, 
            itemId, 
            quantity, 
            'add',
            gameState.globalCollections.items
          );
          
          if ('equipment' in updatedToActor) {
            updatedParty = updatedParty.map(char =>
              char.id === toActorId ? updatedToActor as Character : char
            );
          } else {
            updatedEntities = updatedEntities.map(entity =>
              entity.id === toActorId ? updatedToActor as Entity : entity
            );
          }
        }
  
        onGameStateChange({
          ...gameState,
          party: updatedParty,
          entities: updatedEntities
        });
      });

    // Other handlers remain mostly the same, but update to use findActor where appropriate...
    getItemUse(({ itemId, actorId, playerId }, peerId) => {
        console.log(`Player ${playerId} requested to use item ${itemId} with actor ${actorId}`);
        
        const actor = findActor(gameState, actorId);
        if (!actor) return;
  
        let updatedParty = [...gameState.party];
        let updatedEntities = [...gameState.entities];
  
        const updatedActor = updateActorInventory(
          actor, 
          itemId, 
          1, 
          'remove',
          gameState.globalCollections.items
        );
        
        if ('equipment' in updatedActor) {
          updatedParty = updatedParty.map(char =>
            char.id === actorId ? updatedActor as Character : char
          );
        } else {
          updatedEntities = updatedEntities.map(entity =>
            entity.id === actorId ? updatedActor as Entity : entity
          );
        }
  
        onGameStateChange({
          ...gameState,
          party: updatedParty,
          entities: updatedEntities
        });
      });

    

  // Return functions for both DM and players
  return {
    createItem: (item: Omit<Item, 'id'>) => {
      console.log(`Sending item creation request from ${selfId}`);
      return sendItemCreate({ item, playerId: selfId });
    },

    updateItem: (id: string, updates: Partial<Item>) => {
      console.log(`Sending item update request for ${id} from ${selfId}`);
      return sendItemUpdate({ id, updates, playerId: selfId });
    },

    deleteItem: (id: string) => {
      console.log(`Sending item deletion request for ${id} from ${selfId}`);
      return sendItemDelete({ id, playerId: selfId });
    },

    giveItem: (itemId: string, fromActorId: string, toActorId: string, quantity: number) => {
      console.log(`Sending item transfer request from ${selfId}`);
      return sendItemGive({
        itemId,
        fromActorId,
        toActorId,
        quantity,
        playerId: selfId
      });
    },

    useItem: (itemId: string, actorId: string) => {
      console.log(`Sending item use request from ${selfId}`);
      return sendItemUse({
        itemId,
        actorId,
        playerId: selfId
      });
    },

    }
  };
}

// Hook to use item actions remains the same
export function useItemActions(
  room: Room | undefined,
  gameState: GameState,
  onGameStateChange: (newState: GameState) => void,
  isRoomCreator: boolean
) {
  if (!room) {
    return {
      createItem: () => Promise.resolve(),
      updateItem: () => Promise.resolve(),
      deleteItem: () => Promise.resolve(),
      giveItem: () => Promise.resolve(),
      useItem: () => Promise.resolve(),
    };
  }

  return setupItemActions(room, gameState, onGameStateChange, isRoomCreator);
}
