import React, { useEffect, useState } from 'react';
import type { Room } from 'trystero/torrent';
import { Character, GameState } from '../../types/game';
import StatGauges from '../Player/StatGauges';
import { Sword, Scroll, Zap, Settings } from 'lucide-react';
import { imageManager } from '../../services/ImageManager';
import { InventoryPanel } from '../Player/InventoryPanel';
import { SkillsPanel } from '../Player/SkillsPanel';
import { EquipmentPanel } from '../Player/EquipmentPanel';

interface TabButtonProps {
  icon: React.ReactNode;
  title: string;
  onClick?: () => void;
  upsideDown?: boolean;
}

function TabButton({ icon, title, onClick, upsideDown = false }: TabButtonProps) {
  return (
    <button 
      className="relative aspect-[4/3] min-w-[150px] w-full max-w-[200px] group"
      title={title}
      onClick={onClick}
    >
      {/* Tab shape */}
      <div className="absolute inset-0 overflow-visible">
        <svg 
          viewBox="0 0 134 89" 
          className={`w-full h-full overflow-visible ${upsideDown ? 'rotate-180' : ''}`}
          preserveAspectRatio="none"
        >
          <path 
            d="M51.6936 0C50.2645 0 48.944 0.762396 48.2295 2L1.4641 83C-0.0754968 85.6667 1.849 89 4.9282 89H129.636C132.715 89 134.64 85.6667 133.1 83L86.3346 2C85.6201 0.762395 84.2996 0 82.8705 0H51.6936Z"
            className={`
              fill-transparent
              stroke-blue 
              dark:stroke-cyan
              stroke-[3]
              group-hover:fill-grey/10
              dark:group-hover:fill-offwhite/10
              transition-colors
              drop-shadow-lg
            `}
          />
        </svg>
      </div>

      {/* Icon - not rotated */}
      <div className="absolute inset-0 flex items-center justify-center">
        <div className="w-6 h-6 text-blue dark:text-cyan scale-[1.75]">
          {icon}
        </div>
      </div>
    </button>
  );
}

interface CharacterListProps {
  party: Character[];
  onSelectCharacter: (id: string) => void;
  gameState: GameState;
  onGameStateChange: (newState: GameState) => void;
  room?: Room;
}

export function CharacterList({ 
  party, 
  onSelectCharacter, 
  gameState, 
  onGameStateChange,
  room
}: CharacterListProps) {
  const [characterImages, setCharacterImages] = useState<Record<string, string>>({});
  const [selectedCharacterForInventory, setSelectedCharacterForInventory] = useState<Character | null>(null);
  const [selectedCharacterForSkills, setSelectedCharacterForSkills] = useState<Character | null>(null);
  const [selectedCharacterForEquipment, setSelectedCharacterForEquipment] = useState<Character | null>(null);

  useEffect(() => {
    const loadCharacterImages = async () => {
      const newImages: Record<string, string> = {};
      
      for (const character of party) {
        if (character.image) {
          const thumbnail = imageManager.getThumbnail(character.image);
          if (thumbnail) {
            newImages[character.id] = thumbnail;
            continue;
          }

          try {
            const file = await imageManager.getImage(character.image);
            if (file) {
              const url = URL.createObjectURL(file);
              newImages[character.id] = url;
            }
          } catch (error) {
            console.error(`Failed to load image for character ${character.id}:`, error);
          }
        }
      }
      
      // Cleanup old URLs
      Object.values(characterImages).forEach(url => {
        if (url.startsWith('blob:')) {
          URL.revokeObjectURL(url);
        }
      });

      setCharacterImages(newImages);
    };

    loadCharacterImages();

    return () => {
      Object.values(characterImages).forEach(url => {
        if (url.startsWith('blob:')) {
          URL.revokeObjectURL(url);
        }
      });
    };
  }, [party]);

  return (
    <div className="space-y-4">
      {party.map(character => (
        <div 
          key={character.id}
          className="border-2 border-grey dark:border-offwhite rounded-2xl shadow-md p-4"
        >
          <div className="flex items-center">
            <div className="w-64 flex-shrink-0">
              <h3 className="font-medium font-[Mohave] text-2xl">{character.name}</h3>
            </div>

            <div className="w-48 h-48 flex-shrink-0 mr-8">
              {characterImages[character.id] ? (
                <img
                  src={characterImages[character.id]}
                  alt={character.name}
                  className="w-full h-full object-cover rounded-lg"
                />
              ) : (
                <div className="w-full h-full bg-gray-100 dark:bg-gray-700 rounded-lg flex items-center justify-center">
                  <span className="text-gray-400 text-xs">No image</span>
                </div>
              )}
            </div>

            <div className="flex-1 flex items-center gap-8">
              <StatGauges
                character={character}
                gameState={gameState}
                onGameStateChange={onGameStateChange}
                size="large"
                showSideLabels={true}
              />
              <div className="flex-1 flex items-center justify-center -space-x-8">
                <TabButton
                  icon={<Sword />}
                  title="Equipment"
                  upsideDown={true}
                  onClick={() => setSelectedCharacterForEquipment(character)}
                />
                <TabButton
                  icon={<Scroll />}
                  title="Inventory"
                  onClick={() => setSelectedCharacterForInventory(character)}
                />
                <TabButton
                  icon={<Zap />}
                  title="Skills"
                  upsideDown={true}
                  onClick={() => setSelectedCharacterForSkills(character)}
                />
                <TabButton
                  icon={<Settings />}
                  title="Settings"
                  onClick={() => onSelectCharacter(character.id)}
                />
              </div>
            </div>
          </div>
        </div>
      ))}

      {party.length === 0 && (
        <div className="text-center py-8 text-gray-500">
          No characters in the party yet
        </div>
      )}

      {/* Inventory Modal */}
      {selectedCharacterForInventory && (
        <InventoryPanel
          inventory={selectedCharacterForInventory.inventory}
          onClose={() => setSelectedCharacterForInventory(null)}
          room={room}
          gameState={gameState}
          onGameStateChange={onGameStateChange}
          actorId={selectedCharacterForInventory.id}
          isModal={true}
        />
      )}

      {/* Equipment Modal */}
      {selectedCharacterForEquipment && (
        <EquipmentPanel
          equipment={selectedCharacterForEquipment.equipment}
          onClose={() => setSelectedCharacterForEquipment(null)}
          room={room}
          gameState={gameState}
          onGameStateChange={onGameStateChange}
          actorId={selectedCharacterForEquipment.id}
          isModal={true}
        />
      )}

      {/* Skills Modal */}
      {selectedCharacterForSkills && (
        <SkillsPanel
          skills={selectedCharacterForSkills.skills}
          onClose={() => setSelectedCharacterForSkills(null)}
          room={room}
          gameState={gameState}
          onGameStateChange={onGameStateChange}
          actorId={selectedCharacterForSkills.id}
          isModal={true}
        />
      )}
    </div>
  );
}