import React, { useState } from 'react';
import { InventorySlot, GameState } from '../../types/game';
import { Scroll, Grid, List } from 'lucide-react';
import BasicObjectView from '../ui/BasicObjectView';
import { ItemView } from '../shared/ItemView';
import type { Room } from 'trystero/torrent';
import Modal from '../shared/Modal';

interface InventoryPanelProps {
  inventory: InventorySlot[];
  room?: Room;
  gameState: GameState;
  onGameStateChange: (newState: GameState) => void;
  actorId?: string;
  isModal?: boolean;
  onClose?: () => void;
}

export function InventoryPanel({
  inventory,
  room,
  gameState,
  onGameStateChange,
  actorId,
  isModal = true,
  onClose
}: InventoryPanelProps) {
  const [selectedItem, setSelectedItem] = useState<InventorySlot | null>(null);
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');

  const content = (
    <>
      <div className="flex justify-between items-center mb-4">
        <div className="flex items-center gap-2">
          <Scroll className="w-5 h-5" />
          <h2 className="text-xl font-bold">Inventory</h2>
        </div>
        <div className="flex items-center gap-4">
          <button
            onClick={() => setViewMode(viewMode === 'grid' ? 'list' : 'grid')}
            className="p-2 rounded-md hover:bg-gray-100 dark:hover:bg-gray-700"
          >
            {viewMode === 'grid' ? <List size={20} /> : <Grid size={20} />}
          </button>
        </div>
      </div>

      {inventory.length === 0 ? (
        <div className="flex-1 flex items-center justify-center text-gray-500">
          Inventory is empty
        </div>
      ) : (
        <div className="flex-1 overflow-visible">
          {viewMode === 'grid' ? (
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-4">
              {inventory.map(([item, count]) => (
                <div key={item.id} className="relative">
                  <BasicObjectView
                    name={item.name}
                    imageId={item.image}
                    size="md"
                    onClick={() => setSelectedItem([item, count])}
                    action={{
                      onClick: () => setSelectedItem([item, count]),
                      content: count
                    }}
                  />
                </div>
              ))}
            </div>
          ) : (
            <div className="space-y-2">
              {inventory.map(([item, count]) => (
                <div
                  key={item.id}
                  onClick={() => setSelectedItem([item, count])}
                  className="flex items-center p-4 border rounded-lg hover:bg-gray-50 dark:hover:bg-gray-700 cursor-pointer"
                >
                  <BasicObjectView
                    name={item.name}
                    imageId={item.image}
                    size="sm"
                    action={{
                      onClick: () => setSelectedItem([item, count]),
                      content: count
                    }}
                  />
                  <div className="ml-4">
                    <h4 className="font-medium">{item.name}</h4>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      {/* ItemView Modal */}
      {selectedItem && (
        <Modal
          isOpen={!!selectedItem}
          onClose={() => setSelectedItem(null)}
        >
          <ItemView
            item={selectedItem[0]}
            onClose={() => setSelectedItem(null)}
            room={room}
            gameState={gameState}
            onGameStateChange={onGameStateChange}
            actorId={actorId}
          />
        </Modal>
      )}
    </>
  );

  if (!isModal) {
    return content;
  }

  return (
    <Modal
      isOpen={true}
      onClose={onClose || (() => {})}
      className="max-w-4xl"
    >
      {content}
    </Modal>
  );
}