import React, { useState } from 'react';
import type { Room } from 'trystero/torrent';
import { Skill, GameState } from '../../types/game';
import { SkillEditor } from '../DungeonMaster/SkillEditor';
import { useSkillActions } from '../../actions/skillActions';
import BasicObjectView from '../ui/BasicObjectView';
import Modal from './Modal';
import { Swords, Zap } from 'lucide-react';

interface SkillViewProps {
  skill: Skill;
  onClose?: () => void;
  isRoomCreator?: boolean;
  actorId?: string;
  room?: Room;
  gameState: GameState;
  onGameStateChange: (newState: GameState) => void;
}

export const SkillView: React.FC<SkillViewProps> = ({
  skill,
  onClose,
  isRoomCreator = false,
  actorId,
  room,
  gameState,
  onGameStateChange,
}) => {
  const [showEditor, setShowEditor] = useState(false);
  const [confirmDelete, setConfirmDelete] = useState(false);
  
  const actions = useSkillActions(room, gameState, onGameStateChange, isRoomCreator);

  const handleUse = async () => {
    if (!actorId || !actions) return;
    try {
      await actions.useSkill(skill.id, actorId);
      onClose?.();
    } catch (error) {
      console.error('Failed to use skill:', error);
    }
  };

  const handleDelete = async () => {
    if (!isRoomCreator || !actions) return;
    try {
      await actions.deleteSkill(skill.id);
      onClose?.();
    } catch (error) {
      console.error('Failed to delete skill:', error);
    }
  };

  const handleUpdate = async (updates: Omit<Skill, 'id'>) => {
    if (!actions) return;
    try {
      await actions.updateSkill(skill.id, updates);
      setShowEditor(false);
    } catch (error) {
      console.error('Failed to update skill:', error);
    }
  };

  const isSkillUsable = (): boolean => {
    if (skill.uses === undefined) return true;
    if (skill.usesLeft === undefined) return skill.uses > 0;
    return skill.usesLeft > 0;
  };

  return (
    <div className="bg-white dark:bg-gray-800 rounded-lg shadow-lg p-6 max-w-lg w-full relative">
      <div className="pr-4">
        <div className="flex justify-between items-start mb-4">
          <div className="flex-1">
            <BasicObjectView 
              name={skill.name}
              imageId={skill.image}
              size="lg"
              className="mb-4"
            />
            
            <div className="prose dark:prose-invert max-w-none">
              <p>{skill.description}</p>
            </div>

            <div className="mt-4 space-y-2">
              <div className="flex items-center gap-2">
                <Swords className="w-4 h-4" />
                <span className="text-sm">Damage: {skill.damage}</span>
              </div>
              <div className="flex items-center gap-2">
                <Zap className="w-4 h-4" />
                <span className="text-sm">SP Cost: {skill.spCost}</span>
              </div>
              {skill.uses !== undefined && (
                <div className="text-sm">
                  Uses: {skill.usesLeft ?? skill.uses} / {skill.uses}
                </div>
              )}
              {skill.tags && skill.tags.length > 0 && (
                <div className="flex flex-wrap gap-2 mt-2">
                  {skill.tags.map(tag => (
                    <span 
                      key={tag}
                      className="px-2 py-1 bg-gray-100 dark:bg-gray-700 rounded-full text-xs"
                    >
                      {tag}
                    </span>
                  ))}
                </div>
              )}
            </div>
          </div>

          {/* Action Buttons - only shown if we can perform actions */}
          {room && actions && (
            <div className="flex flex-col gap-2 ml-4">
              {isRoomCreator && (
                <>
                  <button
                    onClick={() => setShowEditor(true)}
                    className="px-3 py-1 bg-blue-500 text-white rounded-md hover:bg-blue-600"
                  >
                    Edit
                  </button>
                  <button
                    onClick={() => setConfirmDelete(true)}
                    className="px-3 py-1 bg-red-500 text-white rounded-md hover:bg-red-600"
                  >
                    Delete
                  </button>
                </>
              )}
              {actorId && isSkillUsable() && (
                <button
                  onClick={handleUse}
                  className="px-3 py-1 bg-green-500 text-white rounded-md hover:bg-green-600"
                >
                  Use
                </button>
              )}
            </div>
          )}
        </div>
      </div>

      {/* Delete Confirmation Modal */}
      {confirmDelete && (
        <Modal
          isOpen={confirmDelete}
          onClose={() => setConfirmDelete(false)}
          title="Confirm Delete"
        >
          <div>
            <p>Are you sure you want to delete this skill? This cannot be undone.</p>
            <div className="flex justify-end gap-2 mt-4">
              <button
                onClick={() => setConfirmDelete(false)}
                className="px-3 py-1 bg-gray-500 text-white rounded-md"
              >
                Cancel
              </button>
              <button
                onClick={handleDelete}
                className="px-3 py-1 bg-red-500 text-white rounded-md"
              >
                Delete
              </button>
            </div>
          </div>
        </Modal>
      )}

      {/* Skill Editor Modal */}
      {showEditor && (
        <Modal
          isOpen={showEditor}
          onClose={() => setShowEditor(false)}
          title="Edit Skill"
        >
          <SkillEditor
            skill={skill}
            onSubmit={handleUpdate}
            onCancel={() => setShowEditor(false)}
          />
        </Modal>
      )}
    </div>
  );
};