// src/actions/equipmentActions.ts
import type { Room } from 'trystero/torrent';
import type { GameState, Item, Character, Equipment, Inventory, InventorySlot } from '../types/game';
import { selfId } from 'trystero';

export const EquipmentActions = {
  EQUIP: 'equipItem',
  UNEQUIP: 'unequipItem',
} as const;

interface EquipItemPayload {
  itemId: string;
  characterId: string;
  slot?: string;
  playerId: string;
}

interface UnequipItemPayload {
  itemId: string;
  characterId: string;
  slot?: string;
  playerId: string;
}

// Helper function to find a character
function findCharacter(gameState: GameState, characterId: string): Character | undefined {
  return gameState.party.find(char => char.id === characterId);
}

// Helper function to validate equipment changes
function validateEquipment(
  character: Character,
  itemToEquip: Item | undefined,
  slot?: string
): boolean {
  if (!itemToEquip || !itemToEquip.isEquippable) return false;

  return true;
}

export function setupEquipmentActions(
  room: Room,
  gameState: GameState,
  onGameStateChange: (newState: GameState) => void,
  isRoomCreator: boolean
) {
  const [sendEquipItem, getEquipItem] = room.makeAction<EquipItemPayload>(EquipmentActions.EQUIP);
  const [sendUnequipItem, getUnequipItem] = room.makeAction<UnequipItemPayload>(EquipmentActions.UNEQUIP);
  if (isRoomCreator) {
    // Handle equipping items
    getEquipItem(({ itemId, characterId, slot, playerId }, peerId) => {
        console.log(`Player ${playerId} requested to equip item ${itemId} on character ${characterId} in slot ${slot}`);
        
        const character = findCharacter(gameState, characterId);
        if (!character) return;
      
        // Find item in character's inventory
        const inventorySlot = character.inventory.find(([item]) => item.id === itemId);
        if (!inventorySlot) return;
      
        const [itemToEquip] = inventorySlot;
      
        if (!validateEquipment(character, itemToEquip, slot)) {
          console.log('Equipment validation failed');
          return;
        }
      
        // Remove from inventory if last item
        const updatedInventory: Inventory = character.inventory
            .map(([item, count]): InventorySlot => {
                if (item.id === itemId) {
                return [item, count - 1];
                }
                return [item, count];
            })
            .filter((slot): slot is InventorySlot => slot[1] > 0);
      
        // Add to equipment
        const updatedEquipment: Equipment = [...character.equipment, itemToEquip];
      
        const updatedCharacter: Character = {
          ...character,
          inventory: updatedInventory,
          equipment: updatedEquipment
        };
      
        onGameStateChange({
          ...gameState,
          party: gameState.party.map(char =>
            char.id === characterId ? updatedCharacter : char
          )
        });
      });

    // Handle unequipping items
    getUnequipItem(({ itemId, characterId, slot, playerId }, peerId) => {
        console.log(`Player ${playerId} requested to unequip item ${itemId} from character ${characterId}`);
        
        const character = findCharacter(gameState, characterId);
        if (!character) return;
      
        // Find item in equipment
        const equippedItem = character.equipment.find(item => item.id === itemId);
        if (!equippedItem) return;
      
        // Remove from equipment
        const updatedEquipment = character.equipment.filter(item => item.id !== itemId);
      
        // Add back to inventory
        const existingSlot = character.inventory.find(([item]) => item.id === itemId);
        const updatedInventory: Inventory = existingSlot
          ? character.inventory.map(([item, count]): InventorySlot => 
              item.id === itemId ? [item, count + 1] : [item, count]
            )
          : [...character.inventory, [equippedItem, 1] as InventorySlot];
      
        const updatedCharacter: Character = {
          ...character,
          inventory: updatedInventory,
          equipment: updatedEquipment
        };
      
        onGameStateChange({
          ...gameState,
          party: gameState.party.map(char =>
            char.id === characterId ? updatedCharacter : char
          )
        });
      });
  }
  // Return functions for both DM and players
  return {
    equipItem: (itemId: string, characterId: string, slot?: string) => {
      console.log(`Sending equip item request from ${selfId}`);
      return sendEquipItem({ itemId, characterId, slot, playerId: selfId });
    },

    unequipItem: (itemId: string, characterId: string, slot?: string) => {
      console.log(`Sending unequip item request from ${selfId}`);
      return sendUnequipItem({ itemId, characterId, slot, playerId: selfId });
    },
  };
}

// Hook to use equipment actions
export function useEquipmentActions(
  room: Room | undefined,
  gameState: GameState,
  onGameStateChange: (newState: GameState) => void,
  isRoomCreator: boolean
) {
  if (!room) {
    return {
      equipItem: () => Promise.resolve(),
      unequipItem: () => Promise.resolve(),
      swapEquipment: () => Promise.resolve(),
      reorderEquipment: () => Promise.resolve()
    };
  }

  return setupEquipmentActions(room, gameState, onGameStateChange, isRoomCreator);
}