import React from 'react';
import type { Room } from 'trystero/torrent';
import { Item, GameState } from '../../types/game';
import { ItemEditor } from '../DungeonMaster/ItemEditor';
import { useItemActions } from '../../actions/itemActions';
import BasicObjectView from '../ui/BasicObjectView';
import Modal from '../shared/Modal';


interface ItemViewProps {
  item: Item;
  onClose?: () => void;
  isRoomCreator?: boolean;
  actorId?: string;
  room?: Room;
  gameState: GameState;
  onGameStateChange: (newState: GameState) => void;
}

export const ItemView: React.FC<ItemViewProps> = ({
  item,
  onClose,
  isRoomCreator = false,
  actorId,
  room,
  gameState,
  onGameStateChange,
}) => {
  const [showEditor, setShowEditor] = React.useState(false);
  const [confirmDelete, setConfirmDelete] = React.useState(false);
  
  const actions = useItemActions(room, gameState, onGameStateChange, isRoomCreator);

  const handleUse = async () => {
    if (!actorId || !actions) return;
    try {
      await actions.useItem(item.id, actorId);
      onClose?.();
    } catch (error) {
      console.error('Failed to use item:', error);
    }
  };

  const handleEquip = async () => {
    if (!actorId || !actions) return;
    try {
      await actions.giveItem(item.id, actorId, actorId, 1);
      onClose?.();
    } catch (error) {
      console.error('Failed to equip item:', error);
    }
  };

  const handleDelete = async () => {
    if (!isRoomCreator || !actions) return;
    try {
      await actions.deleteItem(item.id);
      onClose?.();
    } catch (error) {
      console.error('Failed to delete item:', error);
    }
  };

  const handleUpdate = async (updates: Omit<Item, 'id'>) => {
    if (!actions) return;
    try {
      await actions.updateItem(item.id, updates);
      setShowEditor(false);
    } catch (error) {
      console.error('Failed to update item:', error);
    }
  };

  const canPerformActions = room && actions;

  const content = (
    <div className="pr-4">
      <div className="flex justify-between items-start mb-4">
        <div className="flex-1">
          <BasicObjectView 
            name={item.name}
            imageId={item.image}
            size="lg"
            className="mb-4"
          />
          
          <div className="prose dark:prose-invert max-w-none">
            <p>{item.description}</p>
          </div>

          <div className="mt-4 space-y-2">
            {item.uses !== undefined && (
              <div className="text-sm">
                Uses: {item.usesLeft ?? item.uses} / {item.uses}
              </div>
            )}
            {item.isEquippable && (
              <div className="text-sm">Equippable Item</div>
            )}
            {item.tags && item.tags.length > 0 && (
              <div className="flex flex-wrap gap-2 mt-2">
                {item.tags.map(tag => (
                  <span 
                    key={tag}
                    className="px-2 py-1 bg-gray-100 dark:bg-gray-700 rounded-full text-xs"
                  >
                    {tag}
                  </span>
                ))}
              </div>
            )}
          </div>
        </div>

        {/* Action Buttons - only shown if we can perform actions */}
        {canPerformActions && (
          <div className="flex flex-col gap-2 ml-4">
            {isRoomCreator && (
              <>
                <button
                  onClick={() => setShowEditor(true)}
                  className="px-3 py-1 bg-blue-500 text-white rounded-md hover:bg-blue-600"
                >
                  Edit
                </button>
                <button
                  onClick={() => setConfirmDelete(true)}
                  className="px-3 py-1 bg-red-500 text-white rounded-md hover:bg-red-600"
                >
                  Delete
                </button>
              </>
            )}
            {actorId && (
              <>
                {item.uses !== undefined && (item.usesLeft === undefined || item.usesLeft > 0) && (
                  <button
                    onClick={handleUse}
                    className="px-3 py-1 bg-green-500 text-white rounded-md hover:bg-green-600"
                  >
                    Use
                  </button>
                )}
                {item.isEquippable && (
                  <button
                    onClick={handleEquip}
                    className="px-3 py-1 bg-purple-500 text-white rounded-md hover:bg-purple-600"
                  >
                    Equip
                  </button>
                )}
              </>
            )}
          </div>
        )}
      </div>
    </div>
  );

  return (
    <>
      {/* Main Item View */}
      <div>{content}</div>

      {/* Editor Modal */}
      {showEditor && (
        <Modal
          isOpen={showEditor}
          onClose={() => setShowEditor(false)}
          title="Edit Item"
        >
          <ItemEditor
            onSubmit={handleUpdate}
            onCancel={() => setShowEditor(false)}
          />
        </Modal>
      )}

      {/* Delete Confirmation Modal */}
      {confirmDelete && (
        <Modal
          isOpen={confirmDelete}
          onClose={() => setConfirmDelete(false)}
          title="Confirm Delete"
        >
          <div>
            <p>Are you sure you want to delete this item? This cannot be undone.</p>
            <div className="flex justify-end gap-2 mt-4">
              <button
                onClick={() => setConfirmDelete(false)}
                className="px-3 py-1 bg-gray-500 text-white rounded-md"
              >
                Cancel
              </button>
              <button
                onClick={handleDelete}
                className="px-3 py-1 bg-red-500 text-white rounded-md"
              >
                Delete
              </button>
            </div>
          </div>
        </Modal>
      )}
    </>
  );
};