import React from 'react';
import { Entity } from '../../types/game';
import BasicObjectView from '../ui/BasicObjectView';

interface FieldProps {
  field: Entity[];
}

export function Field({ field }: FieldProps) {
  if (field.length === 0) {
    return null;
  }

  // Single enemy "boss" display
  if (field.length === 1) {
    const enemy = field[0];
    const damageTaken = enemy.maxHp - enemy.hp;
    
    return (
      <div className="mt-6 flex flex-col items-center">
        <h2 className="text-2xl font-bold mb-2">{enemy.name}</h2>
        <div className="w-full flex justify-center">
          <BasicObjectView
            name=""
            imageId={enemy.image}
            size="xl"
            action={damageTaken > 0 ? {
              content: -damageTaken,
              onClick: () => {},
              disabled: true
            } : undefined}
          />
        </div>
        <p className="mt-4 text-gray-600 dark:text-gray-300 text-center max-w-xl">
          {enemy.description}
        </p>
      </div>
    );
  }

  // Multiple enemies grid display
  return (
    <div className="mt-6">
      <div className="grid grid-cols-2 gap-4">
        {field.map(entity => {
          const damageTaken = entity.maxHp - entity.hp;
          
          return (
            <BasicObjectView
              key={entity.id}
              name={entity.name}
              imageId={entity.image}
              size="lg"
              action={damageTaken > 0 ? {
                content: -damageTaken,
                onClick: () => {},
                disabled: true
              } : undefined}
            />
          );
        })}
      </div>
    </div>
  );
}