import React, { useState } from 'react';
import type { Room } from 'trystero/torrent';
import { Item, GameState } from '../../types/game';
import { ItemView } from '../shared/ItemView';
import { useEquipmentActions } from '../../actions/equipmentActions';
import BasicObjectView from '../ui/BasicObjectView';
import Modal from '../shared/Modal';
import { Sword } from 'lucide-react';

interface EquipmentPanelProps {
  equipment: Item[];
  onClose?: () => void;
  room?: Room;
  gameState: GameState;
  onGameStateChange: (newState: GameState) => void;
  actorId?: string;
  isModal?: boolean;
}

export function EquipmentPanel({
  equipment,
  onClose,
  room,
  gameState,
  onGameStateChange,
  actorId,
  isModal = true
}: EquipmentPanelProps) {
  const [selectedItem, setSelectedItem] = useState<Item | null>(null);
  const actions = useEquipmentActions(room, gameState, onGameStateChange, false);

  const handleUnequip = async (itemId: string) => {
    if (!actorId || !actions) return;
    try {
      await actions.unequipItem(itemId, actorId);
    } catch (error) {
      console.error('Failed to unequip item:', error);
    }
  };

  const content = (
    <>
      <div className="flex justify-between items-center mb-4">
        <div className="flex items-center gap-2">
          <Sword className="w-5 h-5" />
          <h2 className="text-xl font-bold">Equipment</h2>
        </div>
      </div>

      {equipment.length === 0 ? (
        <div className="flex-1 flex items-center justify-center text-gray-500">
          No equipment
        </div>
      ) : (
        <div className="flex-1 overflow-auto">
          <div className="space-y-2">
            {equipment.map((item) => (
              <div
                key={item.id}
                className="flex items-center p-4 border rounded-lg bg-white dark:bg-gray-800 shadow-sm"
              >
                <div className="flex-shrink-0">
                  <BasicObjectView
                    name={item.name}
                    imageId={item.image}
                    size="sm"
                    onClick={() => setSelectedItem(item)}
                  />
                </div>
                <div className="ml-4 flex-1 min-w-0">
                  <h4 className="font-medium">{item.name}</h4>
                  <p className="text-sm text-gray-600 dark:text-gray-400 truncate">
                    {item.description}
                  </p>
                </div>
                {actorId && (
                  <button
                    onClick={() => handleUnequip(item.id)}
                    className="ml-4 px-3 py-1 text-sm bg-red-50 text-red-600 rounded-md hover:bg-red-100"
                  >
                    Unequip
                  </button>
                )}
              </div>
            ))}
          </div>
        </div>
      )}

      {/* ItemView Modal */}
      {selectedItem && (
        <Modal
          isOpen={!!selectedItem}
          onClose={() => setSelectedItem(null)}
        >
          <ItemView
            item={selectedItem}
            onClose={() => setSelectedItem(null)}
            room={room}
            gameState={gameState}
            onGameStateChange={onGameStateChange}
            actorId={actorId}
          />
        </Modal>
      )}
    </>
  );

  if (!isModal) {
    return content;
  }

  return (
    <Modal
      isOpen={true}
      onClose={onClose || (() => {})}
      className="max-w-4xl"
    >
      {content}
    </Modal>
  );
}