import React, { useState } from 'react';
import { Entity, GameState, Item, Skill } from '../../../types/game';
import { CoolTabs, CoolTabsList, CoolTabsTrigger, CoolTabsContent } from '../../ui/cooltabs';
import BasicObjectView from '../../ui/BasicObjectView';
import { ItemView } from '../../shared/ItemView';
import { SkillView } from '../../shared/SkillView';
import { EntityEditor } from '../EntityEditor';
import Modal from '../../shared/Modal';
import { Field } from '../../Player/Field';
import  EntityView  from '../../shared/EntityView';

interface EncounterTabProps {
  gameState: GameState;
  onGameStateChange: (newState: GameState) => void;
  room?: Room;
}

export function EncounterTab({ gameState, onGameStateChange, room }: EncounterTabProps) {
  // Selected entities state
  const [selectedEntityIds, setSelectedEntityIds] = useState<Set<string>>(new Set());
  
  // Modal states
  const [showCreateEntity, setShowCreateEntity] = useState(false);
  const [showEntityView, setShowEntityView] = useState(false);
  const [selectedItem, setSelectedItem] = useState<Item | null>(null);
  const [selectedSkill, setSelectedSkill] = useState<Skill | null>(null);
  const [entityToEdit, setEntityToEdit] = useState<Entity | null>(null);

  // Get all selectable entities (both from catalog and field)
  const catalogEntities = gameState.globalCollections.entities;
  const fieldEntities = gameState.field;

  const handleEntitySelect = (entityId: string) => {
    setSelectedEntityIds(prev => {
      const newSet = new Set(prev);
      if (newSet.has(entityId)) {
        newSet.delete(entityId);
      } else {
        newSet.add(entityId);
      }
      return newSet;
    });
  };

  const handleEntityEdit = (entity: Entity) => {
    setEntityToEdit(entity);
    setShowEntityView(true);
  };

  const handleSpawnEntity = (catalogEntityId: string) => {
    const entityToSpawn = gameState.globalCollections.entities.find(e => e.id === catalogEntityId);
    if (!entityToSpawn) return;

    const spawnedEntity: Entity = {
      ...entityToSpawn,
      id: crypto.randomUUID(),
    };

    onGameStateChange({
      ...gameState,
      field: [...gameState.field, spawnedEntity]
    });
  };

  const handleDespawnEntity = (fieldEntityId: string) => {
    onGameStateChange({
      ...gameState,
      field: gameState.field.filter(e => e.id !== fieldEntityId)
    });
  };

  const handleGiveItem = (item: Item) => {
    if (selectedEntityIds.size === 0) return;
    
    const newState = { ...gameState };

    selectedEntityIds.forEach(entityId => {
      // Try to find entity in both field and catalog
      const fieldEntity = newState.field.find(e => e.id === entityId);
      const catalogEntity = newState.globalCollections.entities.find(e => e.id === entityId);
      
      const updateEntityInventory = (entity: Entity) => {
        const existingSlot = entity.inventory.find(([existingItem]) => existingItem.id === item.id);
        if (existingSlot) {
          existingSlot[1] += 1;
        } else {
          entity.inventory.push([item, 1]);
        }
      };

      if (fieldEntity) {
        updateEntityInventory(fieldEntity);
      }
      if (catalogEntity) {
        updateEntityInventory(catalogEntity);
      }
    });

    onGameStateChange(newState);
  };

  const handleGiveSkill = (skill: Skill) => {
    if (selectedEntityIds.size === 0) return;

    const newState = { ...gameState };

    selectedEntityIds.forEach(entityId => {
      // Try to find entity in both field and catalog
      const fieldEntity = newState.field.find(e => e.id === entityId);
      const catalogEntity = newState.globalCollections.entities.find(e => e.id === entityId);
      
      const updateEntitySkills = (entity: Entity) => {
        if (!entity.skills.some(s => s.id === skill.id)) {
          entity.skills.push(skill);
        }
      };

      if (fieldEntity) {
        updateEntitySkills(fieldEntity);
      }
      if (catalogEntity) {
        updateEntitySkills(catalogEntity);
      }
    });

    onGameStateChange(newState);
  };

  return (
    <div className="grid h-full w-full" style={{
      gridTemplateColumns: '75fr 25fr',
      gridTemplateRows: '50fr 50fr',
      gap: '0',
      padding: '1vh'
    }}>
      {/* Entity Catalog Section - Top Left */}
      <div className="row-span-1 overflow-y-auto p-8 border-grey dark:border-offwhite border-2 rounded-xl mt-8 mx-24">
      <h3 className="font-['BrunoAceSC'] bg-grey dark:bg-offwhite rounded-full mb-8 text-offwhite dark:text-grey text-2xl">Entities</h3>
      <div className="flex flex-wrap gap-12 items-start content-start">
        <BasicObjectView
          name="Create New Entity"
          size="md"
          action={{
            onClick: () => setShowCreateEntity(true),
            icon: 'arrow'
          }}
        />
        {catalogEntities.map(entity => (
          <BasicObjectView
            key={entity.id}
            name={entity.name}
            imageId={entity.image}
            size="md"
            onClick={() => handleEntitySelect(entity.id)}
            onEdit={() => handleEntityEdit(entity)}
            action={{
              onClick: () => handleSpawnEntity(entity.id),
              icon: 'plus',
            }}
            border={{
              width: selectedEntityIds.has(entity.id) ? 6 : 2,
              color: selectedEntityIds.has(entity.id) ? 'var(--color-blue)' : undefined
            }}
          />
        ))}
      </div>
    </div>

      {/* Field Section - Right Side */}
      <div className="row-span-2 overflow-y-auto p-8 border-2 border-grey dark:border-offwhite rounded-xl mr-8 mt-8 mb-8">
      <h2 className="text-xl font-bold mb-12 font-['BrunoAceSC']">Field</h2>
      <div className="flex flex-wrap gap-12 items-start content-start">
        {fieldEntities.map(entity => (
          <BasicObjectView
            key={entity.id}
            name={entity.name}
            imageId={entity.image}
            size="md"
            onClick={() => handleEntitySelect(entity.id)}
            onEdit={() => handleEntityEdit(entity)}
            action={{
              onClick: () => handleDespawnEntity(entity.id),
              icon: 'minus',
            }}
            border={{
              width: selectedEntityIds.has(entity.id) ? 4 : 2,
              color: selectedEntityIds.has(entity.id) ? 'var(--color-blue)' : undefined
            }}
          />
        ))}
      </div>
    </div>

      {/* Items/Skills Section - Bottom Left */}
      <div className="row-span-1 overflow-hidden p-8">
        <CoolTabs defaultValue="items" className="flex flex-col h-full">
          <CoolTabsList className="flex-shrink-0">
            <CoolTabsTrigger value="items" tabType="inventory">Items</CoolTabsTrigger>
            <CoolTabsTrigger value="skills" tabType="skills">Skills</CoolTabsTrigger>
          </CoolTabsList>

          <div className="flex-1 min-h-0">
            <CoolTabsContent value="items" className="h-full overflow-auto">
              <div className="flex flex-wrap gap-12 p-4 items-start content-start">
                {gameState.globalCollections.items.map(item => (
                  <BasicObjectView
                    key={item.id}
                    name={item.name}
                    imageId={item.image}
                    size="md"
                    onClick={() => setSelectedItem(item)}
                    action={{
                      onClick: () => handleGiveItem(item),
                      icon: 'plus',
                      disabled: selectedEntityIds.size === 0
                    }}
                  />
                ))}
              </div>
            </CoolTabsContent>

            <CoolTabsContent value="skills" className="h-full overflow-auto">
              <div className="flex flex-wrap gap-12 p-4 items-start content-start">
                {gameState.globalCollections.skills.map(skill => (
                  <BasicObjectView
                    key={skill.id}
                    name={skill.name}
                    imageId={skill.image}
                    size="md"
                    onClick={() => setSelectedSkill(skill)}
                    action={{
                      onClick: () => handleGiveSkill(skill),
                      icon: 'plus',
                      disabled: selectedEntityIds.size === 0
                    }}
                  />
                ))}
              </div>
            </CoolTabsContent>
          </div>
        </CoolTabs>
      </div>

      {/* Modals */}
      {showCreateEntity && (
    <Modal
      isOpen={showCreateEntity}
      onClose={() => setShowCreateEntity(false)}
      title="Create New Entity"
    >
      <EntityEditor
        onSave={async (entity) => {
          onGameStateChange({
            ...gameState,
            globalCollections: {
              ...gameState.globalCollections,
              entities: [...gameState.globalCollections.entities, { ...entity, id: crypto.randomUUID() }]
            }
          });
          setShowCreateEntity(false);
        }}
        onUpdate={async (id, updates) => {
          onGameStateChange({
            ...gameState,
            globalCollections: {
              ...gameState.globalCollections,
              entities: gameState.globalCollections.entities.map(e =>
                e.id === id ? { ...e, ...updates } : e
              )
            }
          });
        }}
        onClose={() => setShowCreateEntity(false)}
      />
    </Modal>
  )}

      {showEntityView && entityToEdit && (
        <Modal
          isOpen={showEntityView}
          onClose={() => {
            setShowEntityView(false);
            setEntityToEdit(null);
          }}
          title={entityToEdit.name}
        >
          <EntityView
            entity={entityToEdit}
            onClose={() => {
              setShowEntityView(false);
              setEntityToEdit(null);
            }}
            gameState={gameState}
            onGameStateChange={onGameStateChange}
            room={room}
          />
        </Modal>
      )}

      {selectedItem && (
        <Modal
          isOpen={!!selectedItem}
          onClose={() => setSelectedItem(null)}
          title={selectedItem.name}
        >
          <ItemView
            item={selectedItem}
            onClose={() => setSelectedItem(null)}
            gameState={gameState}
            onGameStateChange={onGameStateChange}
            room={room}
            isRoomCreator={true}
          />
        </Modal>
      )}

      {selectedSkill && (
        <Modal
          isOpen={!!selectedSkill}
          onClose={() => setSelectedSkill(null)}
          title={selectedSkill.name}
        >
          <SkillView
            skill={selectedSkill}
            onClose={() => setSelectedSkill(null)}
            gameState={gameState}
            onGameStateChange={onGameStateChange}
            room={room}
            isRoomCreator={true}
          />
        </Modal>
      )}
    </div>
  );
}