import React, { useState } from 'react';
import { GameState, Item, Skill, InventorySlot } from '../../../types/game';
import { useItemActions } from '../../../actions/itemActions';
import { useSkillActions } from '../../../actions/skillActions';
import { CoolTabs, CoolTabsList, CoolTabsTrigger, CoolTabsContent } from '../../ui/cooltabs';
import BasicObjectView from '../../ui/BasicObjectView';
import { ItemView } from '../../shared/ItemView';
import { SkillView } from '../../shared/SkillView';
import { ItemEditor } from '../ItemEditor';
import { SkillEditor } from '../SkillEditor';
import Modal from '../../shared/Modal';

interface CatalogTabProps {
  gameState: GameState;
  onGameStateChange: (newState: GameState) => void;
  room?: Room;
}

export function CatalogTab({ gameState, onGameStateChange, room }: CatalogTabProps) {
  const [selectedCharacters, setSelectedCharacters] = useState<Set<string>>(new Set());
  const [showCreateItem, setShowCreateItem] = useState(false);
  const [showCreateSkill, setShowCreateSkill] = useState(false);
  const [selectedItem, setSelectedItem] = useState<Item | null>(null);
  const [selectedSkill, setSelectedSkill] = useState<Skill | null>(null);

  const itemActions = useItemActions(room, gameState, onGameStateChange, true);
  const skillActions = useSkillActions(room, gameState, onGameStateChange, true);

  const handleCharacterSelect = (characterId: string) => {
    setSelectedCharacters(prev => {
      const newSet = new Set(prev);
      if (newSet.has(characterId)) {
        newSet.delete(characterId);
      } else {
        newSet.add(characterId);
      }
      return newSet;
    });
  };

  const handleGiveItem = (item: Item) => {
    if (selectedCharacters.size === 0) return;

    const newState = { ...gameState };

    // For each selected character/entity
    selectedCharacters.forEach(actorId => {
      // Find the actor in either party or entities
      const partyMember = newState.party.find(char => char.id === actorId);
      if (partyMember) {
        // Check if they already have this item
        const existingSlot = partyMember.inventory.find(([existingItem]) => existingItem.id === item.id);
        if (existingSlot) {
          existingSlot[1] += 1; // Increment count
        } else {
          partyMember.inventory.push([item, 1]); // Add new item
        }
      }

      const entity = newState.entities.find(e => e.id === actorId);
      if (entity) {
        const existingSlot = entity.inventory.find(([existingItem]) => existingItem.id === item.id);
        if (existingSlot) {
          existingSlot[1] += 1;
        } else {
          entity.inventory.push([item, 1]);
        }
      }
    });

    onGameStateChange(newState);
  };

  const handleGiveSkill = (skill: Skill) => {
    if (selectedCharacters.size === 0) return;

    const newState = { ...gameState };

    selectedCharacters.forEach(actorId => {
      // Find the actor in either party or entities
      const partyMember = newState.party.find(char => char.id === actorId);
      if (partyMember && !partyMember.skills.some(s => s.id === skill.id)) {
        partyMember.skills.push(skill);
      }

      const entity = newState.entities.find(e => e.id === actorId);
      if (entity && !entity.skills.some(s => s.id === skill.id)) {
        entity.skills.push(skill);
      }
    });

    onGameStateChange(newState);
  };

  return (
    <div 
      className="grid h-full w-full"
      style={{
        gridTemplateRows: '30fr 70fr',
        gap: '0',
        padding: '1vh'
      }}
    >
      {/* Character Selection Section - Top 30% */}
      <div className="w-full h-full flex flex-col justify-center px-24">
        <div className="w-full border-2 border-grey dark:border-offwhite bg-transparent rounded-lg p-4">
          <h3 className="bg-grey dark:bg-offwhite font-['BrunoAceSC'] rounded-full text-xl text-offwhite dark:text-grey mb-4">Characters</h3>
          <div className="flex overflow-x-auto space-x-4 justify-center items-center">
            {gameState.party.map(character => (
              <div
                key={character.id}
                className="flex-shrink-0 cursor-pointer hover:cursor-pointer"
                onClick={() => handleCharacterSelect(character.id)}
              >
                <BasicObjectView
                  name={character.name}
                  imageId={character.image}
                  size="lg"
                  border={{
                    width: selectedCharacters.has(character.id) ? 6 : 2,
                    color: selectedCharacters.has(character.id) ? 'var(--color-blue)' : undefined
                  }}
                />
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Items and Skills Tabs - Bottom 70% */}
      <div className="w-full h-full flex flex-col p-8">
        <CoolTabs defaultValue="items" className="flex-1 flex flex-col">
          <CoolTabsList className="flex-shrink-0">
            <CoolTabsTrigger value="items" tabType="inventory">Items</CoolTabsTrigger>
            <CoolTabsTrigger value="skills" tabType="skills">Skills</CoolTabsTrigger>
          </CoolTabsList>

          <div className="flex-1 min-h-0">
          <CoolTabsContent value="items" className="h-full overflow-y-auto">
            <div className="flex flex-wrap gap-12 p-4 items-start content-start">
              <BasicObjectView
                name="Create New Item"
                size="md"
                action={{
                  onClick: () => setShowCreateItem(true),
                  icon: 'arrow'
                }}
              />
              {gameState.globalCollections.items.map(item => {
                const handleItemClick = () => setSelectedItem(item);
                const handleItemAction = () => handleGiveItem(item);

                return (
                  <BasicObjectView
                    key={item.id}
                    name={item.name}
                    imageId={item.image}
                    size="md"
                    onClick={handleItemClick}
                    action={{
                      onClick: handleItemAction,
                      icon: 'plus',
                      disabled: selectedCharacters.size === 0
                    }}
                  />
                );
              })}
            </div>
          </CoolTabsContent>

          <CoolTabsContent value="skills" className="h-full overflow-y-auto">
    <div className="flex flex-wrap gap-12 p-4 items-start content-start">
      <BasicObjectView
        name="Create New Skill"
        size="md"
        action={{
          onClick: () => setShowCreateSkill(true),
          icon: 'arrow'
        }}
      />
      {gameState.globalCollections.skills.map(skill => {
        const handleSkillClick = () => setSelectedSkill(skill);
        const handleSkillAction = () => handleGiveSkill(skill);

        return (
          <BasicObjectView
            key={skill.id}
            name={skill.name}
            imageId={skill.image}
            size="md"
            onClick={handleSkillClick}
            action={{
              onClick: handleSkillAction,
              icon: 'plus',
              disabled: selectedCharacters.size === 0
            }}
          />
        );
      })}
    </div>
  </CoolTabsContent>
          </div>
        </CoolTabs>
      </div>

      {/* Modals */}
      {showCreateItem && (
  <Modal
    isOpen={showCreateItem}
    onClose={() => setShowCreateItem(false)}
    title="Create New Item"
  >
    <ItemEditor
      onSubmit={async (item) => {
        try {
          await itemActions?.createItem(item);
          // Update local game state
          onGameStateChange({
            ...gameState,
            globalCollections: {
              ...gameState.globalCollections,
              items: [...gameState.globalCollections.items, { ...item, id: crypto.randomUUID() }]
            }
          });
          setShowCreateItem(false);
        } catch (error) {
          console.error('Failed to create item:', error);
        }
      }}
      onCancel={() => setShowCreateItem(false)}
    />
  </Modal>
)}

{showCreateSkill && (
  <Modal
    isOpen={showCreateSkill}
    onClose={() => setShowCreateSkill(false)}
    title="Create New Skill"
  >
    <SkillEditor
      onSubmit={async (skill) => {
        try {
          await skillActions?.createSkill(skill);
          // Update local game state
          onGameStateChange({
            ...gameState,
            globalCollections: {
              ...gameState.globalCollections,
              skills: [...gameState.globalCollections.skills, { ...skill, id: crypto.randomUUID() }]
            }
          });
          setShowCreateSkill(false);
        } catch (error) {
          console.error('Failed to create skill:', error);
        }
      }}
      onCancel={() => setShowCreateSkill(false)}
    />
  </Modal>
)}

      {selectedItem && (
        <Modal
          isOpen={!!selectedItem}
          onClose={() => setSelectedItem(null)}
          title={selectedItem.name}
        >
          <ItemView
            item={selectedItem}
            onClose={() => setSelectedItem(null)}
            gameState={gameState}
            onGameStateChange={onGameStateChange}
            room={room}
            isRoomCreator={true}
          />
        </Modal>
      )}

      {selectedSkill && (
        <Modal
          isOpen={!!selectedSkill}
          onClose={() => setSelectedSkill(null)}
          title={selectedSkill.name}
        >
          <SkillView
            skill={selectedSkill}
            onClose={() => setSelectedSkill(null)}
            gameState={gameState}
            onGameStateChange={onGameStateChange}
            room={room}
            isRoomCreator={true}
          />
        </Modal>
      )}
    </div>
  );
}